        function getMonthKey(dateStr) {
            if (!dateStr) return "";
            const parts = String(dateStr).split("-");
            if (parts.length >= 2) return `${parts[0]}-${parts[1]}`;
            return "";
        }

        function getMonthLabel(monthKey) {
            if (!monthKey) return "-";

            const parts = String(monthKey).split("-");
            const year = parts[0];
            const monthIndex = parseInt(parts[1], 10) - 1;

            const months = [
                "Jan", "Feb", "Mar", "Apr", "May", "Jun",
                "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"
            ];

            return months[monthIndex] ? `${months[monthIndex]} ${year}` : "-";
        }

        function getMonthDateRange(monthKey) {
            const parts = String(monthKey || "").split("-");
            const year = parseInt(parts[0], 10);
            const month = parseInt(parts[1], 10);

            if (!year || !month) {
                return {
                    start: "",
                    end: ""
                };
            }

            const startDate = new Date(year, month - 1, 1);
            const endDate = new Date(year, month, 0);

            return {
                start: formatDateInput(startDate),
                end: formatDateInput(endDate)
            };
        }

        function getPreviousMonthKey(monthKey) {
            const parts = String(monthKey || "").split("-");
            const year = parseInt(parts[0], 10);
            const month = parseInt(parts[1], 10);

            if (!year || !month) return "";

            const previousMonthDate = new Date(year, month - 2, 1);
            const previousYear = previousMonthDate.getFullYear();
            const previousMonth = String(previousMonthDate.getMonth() + 1).padStart(2, "0");

            return `${previousYear}-${previousMonth}`;
        }

        function toObjArray(message) {
            const keys = Array.isArray(message?.keys) ? message.keys : [];
            const values = Array.isArray(message?.values) ? message.values : [];

            if (!keys.length || !values.length) return [];

            return values.map(row => {
                return Object.fromEntries(
                    keys.map((key, index) => [key, row[index]])
                );
            });
        }

        /*
         * Patient is a Link field. Its value is the Patient document name,
         * so it must be matched exactly. Do not lowercase or collapse spaces.
         */
        function getPatientDocKey(value) {
            return String(value ?? "");
        }

        function splitIntoChunks(values, chunkSize) {
            const size = Math.max(1, parseInt(chunkSize || 500, 10));
            const chunks = [];

            for (let index = 0; index < values.length; index += size) {
                chunks.push(values.slice(index, index + size));
            }

            return chunks;
        }

        /*
         * reportview.get returns at most page_length rows.
         * Fetch every page so Administrator results are not truncated.
         */
        async function fetchAllReportRows(options) {
            const {
                doctype,
                fields,
                filters = [],
                orderBy = "modified desc, name desc",
                pageLength = 5000
            } = options || {};

            if (!doctype) {
                throw new Error("fetchAllReportRows: doctype is required");
            }

            let start = 0;
            let pageNumber = 0;
            const allRows = [];

            while (true) {
                const response = await frappe.call({
                    method: "frappe.desk.reportview.get",
                    args: {
                        doctype: doctype,
                        fields: fields || ["name"],
                        filters: filters,
                        order_by: orderBy,
                        start: start,
                        page_length: pageLength
                    }
                });

                const batch = toObjArray(response.message);

                allRows.push(...batch);

                if (batch.length < pageLength) {
                    break;
                }

                start += batch.length;
                pageNumber += 1;

                if (pageNumber > 100) {
                    throw new Error(
                        `fetchAllReportRows stopped after ${allRows.length} ${doctype} rows`
                    );
                }
            }

            return allRows;
        }

        /*
         * Large IN filters are split into smaller requests.
         * This avoids oversized requests when Administrator can see thousands
         * of clients.
         */
        async function fetchRowsByPatientChunks(options) {
            const {
                doctype,
                fields,
                patientNames,
                linkField = "patient",
                extraFilters = [],
                orderBy = "modified desc, name desc",
                chunkSize = 500,
                pageLength = 5000
            } = options || {};

            const exactPatientNames = [
                ...new Set(
                    (patientNames || [])
                        .map(getPatientDocKey)
                        .filter(Boolean)
                )
            ];

            if (!exactPatientNames.length) {
                return [];
            }

            const rows = [];

            for (const patientChunk of splitIntoChunks(exactPatientNames, chunkSize)) {
                const chunkRows = await fetchAllReportRows({
                    doctype: doctype,
                    fields: fields,
                    filters: [
                        [doctype, linkField, "in", patientChunk],
                        ...extraFilters
                    ],
                    orderBy: orderBy,
                    pageLength: pageLength
                });

                rows.push(...chunkRows);
            }

            return rows;
        }

        function isSubmittedSession(row) {
            return parseInt(row?.docstatus || 0, 10) === 1;
        }

        function sortSessionsAsc(sessions) {
            return [...(sessions || [])].sort((a, b) => {
                const dateCompare = String(a.start_date || a.date || "").localeCompare(String(b.start_date || b.date || ""));
                if (dateCompare !== 0) return dateCompare;

                return String(a.name || "").localeCompare(String(b.name || ""));
            });
        }

        function getLastAvailableWeight(sessions) {
            const sortedSessions = sortSessionsAsc(sessions);

            for (let i = sortedSessions.length - 1; i >= 0; i--) {
                const afterWeight = toNumber(sortedSessions[i].after_weight);
                const beforeWeight = toNumber(sortedSessions[i].before_weight);

                if (afterWeight > 0) return afterWeight;
                if (beforeWeight > 0) return beforeWeight;
            }

            return 0;
        }

        function getFirstAvailableWeight(sessions) {
            const sortedSessions = sortSessionsAsc(sessions);

            for (let i = 0; i < sortedSessions.length; i++) {
                const beforeWeight = toNumber(sortedSessions[i].before_weight);
                const afterWeight = toNumber(sortedSessions[i].after_weight);

                if (beforeWeight > 0) return beforeWeight;
                if (afterWeight > 0) return afterWeight;
            }

            return 0;
        }

        function getSessionDifference(session) {
            const beforeWeight = toNumber(session.before_weight);
            const afterWeight = toNumber(session.after_weight);

            if (!beforeWeight || !afterWeight) return 0;

            return beforeWeight - afterWeight;
        }

        function displayDifference(value) {
            const num = toNumber(value);

            if (num > 0) {
                return `${num.toFixed(1)} kg ↓ Loss`;
            }

            if (num < 0) {
                return `${Math.abs(num).toFixed(1)} kg ↑ Gain`;
            }

            return "0.0 kg No Change";
        }

        function differenceClass(value) {
            const num = toNumber(value);

            if (num > 0) return "loss-good";
            if (num < 0) return "weight-gain";
            return "loss-neutral";
        }

        function showLoader(message) {
            if (window.frappe && frappe.dom && frappe.dom.freeze) {
                frappe.dom.freeze(message || "Loading...");
            }
        }

        function hideLoader() {
            if (window.frappe && frappe.dom && frappe.dom.unfreeze) {
                frappe.dom.unfreeze();
            }
        }

        function populateMonthFilter() {
            if (!monthFilterEl) return;

            const startDate = new Date(MONTH_START_FROM);
            const today = new Date();

            const start = new Date(startDate.getFullYear(), startDate.getMonth(), 1);
            const end = new Date(today.getFullYear(), today.getMonth(), 1);

            const options = [];

            let cursor = new Date(start);

            while (cursor <= end) {
                const key = `${cursor.getFullYear()}-${String(cursor.getMonth() + 1).padStart(2, "0")}`;
                options.push({
                    key: key,
                    label: getMonthLabel(key)
                });

                cursor.setMonth(cursor.getMonth() + 1);
            }

            options.reverse();

            monthFilterEl.innerHTML = options.map(option => {
                return `<option value="${escapeHtml(option.key)}">${escapeHtml(option.label)}</option>`;
            }).join("");

            const currentKey = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, "0")}`;
            monthFilterEl.value = currentKey;
        }

