        }
        
        async function fetchOpenCardsCount() {
            if (!totalOpenCardsEl) return;

            /*
             * Prevent an older refresh from overwriting a newer result.
             */
            const requestSequence = ++openCardsFetchSequence;

            totalOpenCardsEl.innerText = "...";

            try {
                const today = formatDateInput(new Date());

                /*
                 * Therapy Session is the primary record.
                 * Fetch every submitted Slimming session in the Open Card
                 * attendance window, including its exact linked Therapy Plan.
                 */
                const fetchedAttendanceRows = await fetchAllReportRows({
                    doctype: "Therapy Session",
                    fields: [
                        "name",
                        "patient",
                        "therapy_plan",
                        "start_date",
                        "service_unit",
                        "docstatus"
                    ],
                    filters: [
                        ["Therapy Session", "service_unit", "=", SLIMMING_VALUE],
                        ["Therapy Session", "docstatus", "=", 1],
                        [
                            "Therapy Session",
                            "start_date",
                            ">=",
                            CARD_ACTIVITY_START_DATE
                        ],
                        [
                            "Therapy Session",
                            "start_date",
                            "<=",
                            today
                        ]
                    ],
                    orderBy: "start_date desc, name desc",
                    pageLength: 5000
                });

                if (requestSequence !== openCardsFetchSequence) return;

                /*
                 * Offset pagination can theoretically overlap while live data
                 * is changing. Deduplicate by the Therapy Session document name.
                 */
                const seenSessionNames = new Set();

                const attendanceRows = fetchedAttendanceRows
                    .filter(isSubmittedSession)
                    .filter(session => {
                        const sessionName = String(session.name || "");

                        if (!sessionName) return false;
                        if (seenSessionNames.has(sessionName)) return false;

                        seenSessionNames.add(sessionName);
                        return true;
                    })
                    .sort((a, b) => {
                        const dateCompare =
                            String(b.start_date || "")
                                .localeCompare(String(a.start_date || ""));

                        if (dateCompare !== 0) return dateCompare;

                        return String(b.name || "")
                            .localeCompare(String(a.name || ""));
                    });

                /*
                 * The first row for each exact Patient Link value is that
                 * client's latest qualifying submitted Slimming session.
                 */
                const latestSlimmingSessionByPatient = new Map();

                attendanceRows.forEach(session => {
                    const patientKey =
                        getPatientDocKey(session.patient);

                    if (!patientKey) return;

                    if (!latestSlimmingSessionByPatient.has(patientKey)) {
                        latestSlimmingSessionByPatient.set(
                            patientKey,
                            session
                        );
                    }
                });

                const latestSlimmingSessions = [
                    ...latestSlimmingSessionByPatient.values()
                ];

                const patientNames = latestSlimmingSessions
                    .map(session => getPatientDocKey(session.patient))
                    .filter(Boolean);

                if (!patientNames.length) {
                    if (requestSequence !== openCardsFetchSequence) return;

                    openCardSummaryRows = [];
                    renderOpenCardsCount();
                    return;
                }

                const linkedPlanNames = [
                    ...new Set(
                        latestSlimmingSessions
                            .map(session =>
                                String(session.therapy_plan || "")
                            )
                            .filter(Boolean)
                    )
                ];

                /* =====================================================
                   FETCH CLIENT DETAILS USING EXACT PATIENT LINKS
                ===================================================== */
                const patientRows = await fetchRowsByPatientChunks({
                    doctype: "Patient",
                    fields: [
                        "name",
                        "mobile",
                        "phone",
                        "branch_name"
                    ],
                    patientNames: patientNames,
                    linkField: "name",
                    orderBy: "name asc",
                    chunkSize: 500,
                    pageLength: 5000
                });

                if (requestSequence !== openCardsFetchSequence) return;

                const patientInfoByName = new Map();

                patientRows.forEach(patient => {
                    const patientKey =
                        getPatientDocKey(patient.name);

                    if (!patientKey) return;

                    patientInfoByName.set(patientKey, {
                        mobile:
                            patient.mobile ||
                            patient.phone ||
                            "",
                        branch:
                            patient.branch_name ||
                            ""
                    });
                });

                /* =====================================================
                   FETCH ONLY THE EXACT PLANS LINKED TO LATEST SESSIONS

                   Therapy Plan category is intentionally not filtered.
                   The Therapy Session has already established that the
                   attendance belongs to Slimming.
                ===================================================== */
                const linkedPlans = linkedPlanNames.length
                    ? await fetchRowsByPatientChunks({
                        doctype: "Therapy Plan",
                        fields: [
                            "name",
                            "patient",
                            "branch",
                            "category",
                            "status",
                            "start_date",
                            "modified"
                        ],
                        patientNames: linkedPlanNames,
                        linkField: "name",
                        orderBy: "modified desc, name desc",
                        chunkSize: 500,
                        pageLength: 5000
                    })
                    : [];

                if (requestSequence !== openCardsFetchSequence) return;

                const planByName = new Map();

                linkedPlans.forEach(plan => {
                    const planName = String(plan.name || "");

                    if (!planName) return;

                    planByName.set(planName, plan);
                });

                const candidateRows = latestSlimmingSessions.map(session => {
                    const patientName =
                        getPatientDocKey(session.patient);

                    const patientKey = patientName;

                    const linkedPlanName =
                        String(session.therapy_plan || "");

                    const linkedPlan =
                        planByName.get(linkedPlanName) || {};

                    const patientInfo =
                        patientInfoByName.get(patientKey) || {};

                    const mobile =
                        patientInfo.mobile || "";

                    /*
                     * The branch of the exact linked Therapy Plan is primary.
                     * Patient.branch_name is used only when that plan branch is
                     * blank.
                     */
                    const branch =
                        linkedPlan.branch ||
                        patientInfo.branch ||
                        "";

                    const linkedPlanPatient =
                        getPatientDocKey(linkedPlan.patient);

                    return {
                        patient: patientName,
                        patient_key: patientKey,

                        therapy_session:
                            session.name || "",
                        therapy_session_date:
                            session.start_date || "",

                        therapy_plan:
                            linkedPlanName,
                        plan_found:
                            Boolean(linkedPlan.name),
                        plan_patient_matches:
                            Boolean(linkedPlan.name) &&
                            linkedPlanPatient === patientKey,
                        plan_category:
                            linkedPlan.category || "",
                        plan_status:
                            linkedPlan.status || "",

                        mobile: mobile,
                        masked_mobile:
                            maskMobileNumber(mobile),

                        branch: branch
                    };
                });

                const audit = {
                    unlinkedSessions: 0,
                    inaccessibleOrMissingPlans: 0,
                    planPatientMismatches: 0,
                    completedLinkedPlans: 0,
                    invalidBranches: 0
                };

                openCardSummaryRows = candidateRows
                    .filter(row => {
                        const planStatus =
                            cleanText(row.plan_status);

                        const branchName =
                            cleanText(row.branch);

                        if (!row.therapy_plan) {
                            audit.unlinkedSessions += 1;
                            return false;
                        }

                        if (!row.plan_found) {
                            audit.inaccessibleOrMissingPlans += 1;
                            return false;
                        }

                        if (!row.plan_patient_matches) {
                            audit.planPatientMismatches += 1;
                            return false;
                        }

                        if (planStatus === "completed") {
                            audit.completedLinkedPlans += 1;
                            return false;
                        }

                        if (
                            !branchName ||
                            branchName === "testing branch" ||
                            branchName === "head office"
                        ) {
                            audit.invalidBranches += 1;
                            return false;
                        }

                        return true;
