/* =====================================================
   COMMON OPEN CARDS FILTER
   Used by KPI, modal and Excel export
===================================================== */
function getFilteredOpenCardRows() {
    const selectedBranch =
        branchFilterEl?.value || "";

    const selectedClient =
        getPatientDocKey(selectedClientName);

    let rows = [...openCardSummaryRows];

    if (selectedBranch) {
        rows = rows.filter(row => {
            return row.branch === selectedBranch;
        });
    }

    if (selectedClient) {
        rows = rows.filter(row => {
            return getPatientDocKey(row.patient) === selectedClient;
        });
    }

    return rows.sort((a, b) => {
        const branchCompare =
            String(a.branch || "")
                .localeCompare(String(b.branch || ""));

        if (branchCompare !== 0) {
            return branchCompare;
        }

        return String(a.patient || "")
            .localeCompare(String(b.patient || ""));
    });
}


/* =====================================================
   UPDATE OPEN CARDS KPI
===================================================== */
function renderOpenCardsCount() {
    const rows = getFilteredOpenCardRows();

    if (totalOpenCardsEl) {
        totalOpenCardsEl.innerText =
            rows.length.toLocaleString("en-IN");
    }

    /*
     * If the popup is currently open,
     * update its table using the same filters.
     */
    if (
        openCardsModalOverlay &&
        !openCardsModalOverlay.classList.contains("hidden")
    ) {
        renderOpenCardsModalTable();
    }
}


/* =====================================================
   OPEN MODAL
===================================================== */
function openOpenCardsModal() {
    if (!openCardsModalOverlay) return;

    openCardsModalCurrentPage = 1;

    openCardsModalOverlay.classList.remove("hidden");

    renderOpenCardsModalTable();
}


/* =====================================================
   CLOSE MODAL
===================================================== */
function closeOpenCardsModal() {
    if (!openCardsModalOverlay) return;

    openCardsModalOverlay.classList.add("hidden");
}


/* =====================================================
   RENDER OPEN CARDS TABLE
===================================================== */
function renderOpenCardsModalTable() {
    const rows = getFilteredOpenCardRows();

    const selectedBranch =
        branchFilterEl?.value || "All Branches";

    const selectedClient =
        selectedClientName || "";

    if (openCardsModalSummaryEl) {
        let summary =
            `${rows.length.toLocaleString("en-IN")} open cards`;

        summary += ` · ${selectedBranch}`;

        if (selectedClient) {
            summary += ` · ${selectedClient}`;
        }

        openCardsModalSummaryEl.innerText = summary;
    }

    if (!openCardsTableBody) return;

    if (!rows.length) {
        openCardsTableBody.innerHTML = `
            <tr>
                <td
                    colspan="3"
                    class="wl-empty-row"
                >
                    No Open Cards found for the applied filters
                </td>
            </tr>
        `;

        if (openCardsPaginationEl) {
            openCardsPaginationEl.innerHTML = "";
        }

        return;
    }

    const totalPages =
        Math.ceil(
            rows.length / OPEN_CARDS_PAGE_LIMIT
        );

    if (openCardsModalCurrentPage > totalPages) {
        openCardsModalCurrentPage = 1;
    }

    const start =
        (openCardsModalCurrentPage - 1) *
        OPEN_CARDS_PAGE_LIMIT;

    const end =
        start + OPEN_CARDS_PAGE_LIMIT;

    const pageRows = rows.slice(start, end);

    openCardsTableBody.innerHTML =
        pageRows.map(row => {
            return `
                <tr>
                    <td>
                        <b>
                            ${escapeHtml(row.patient || "-")}
                        </b>
                    </td>

                    <td title="${escapeHtml(row.mobile || "")}">
                        ${
                            escapeHtml(
                                row.masked_mobile || "-"
                            )
                        }
                    </td>

                    <td>
                        ${escapeHtml(row.branch || "-")}
                    </td>
                </tr>
            `;
        }).join("");

    renderPagination(
        openCardsPaginationEl,
        openCardsModalCurrentPage,
        totalPages,
        function (page) {
            openCardsModalCurrentPage = page;
            renderOpenCardsModalTable();
        }
    );
}


