                        }
                    });

                    allWeightSessions = toObjArray(allWeightSessionsRes.message)
                        .filter(isSubmittedSession);
                }

                /* =====================================================
                   4. THERAPY PLANS
                   Used for branch and total sessions
                ===================================================== */
                const allPlansRes = await frappe.call({
                    method: "frappe.desk.reportview.get",
