                    const plan = bestPlanByPatient[patientKey] || {};
                    const planStatus = cleanText(plan.status);
                    const isPlanCompleted = planStatus === "completed";

                    /* -----------------------------
                       First Slimming Session
                    ------------------------------*/
                    /*
                     * Card type is determined by the client's latest submitted
                     * slimming attendance, not their joining or first-session date.
                     */
                    const firstSlimmingSessionDate =
                        lifetimeSessions.length
                            ? lifetimeSessions[0].start_date
                            : "";
                    
                    const latestSlimmingSessionDate =
                        lifetimeSessions.length
                            ? lifetimeSessions[lifetimeSessions.length - 1].start_date
                            : "";
                    
                    const today = formatDateInput(new Date());
                    
                    const isOpenCard = Boolean(
                        latestSlimmingSessionDate &&
                        latestSlimmingSessionDate >= CARD_ACTIVITY_START_DATE &&
                        latestSlimmingSessionDate <= today &&
                        !isPlanCompleted
                    );
                    
                    const isClosedCard = Boolean(
                        latestSlimmingSessionDate &&
                        latestSlimmingSessionDate < CARD_ACTIVITY_START_DATE
                    );

                    /*
                    Open card popup should show all sessions,
                    because once client is an Open Card,
                    their entire history belongs to that card.
                    */
                    const modalSessions = lifetimeSessions;

                    const joinedWeight = getFirstAvailableWeight(modalSessions);
                    const presentWeight = getLastAvailableWeight(modalSessions);

                    let totalChange = 0;

                    if (joinedWeight && presentWeight) {
                        totalChange = joinedWeight - presentWeight;
                    }

                    const firstSessionDate =
                        modalSessions.length
                            ? modalSessions[0].start_date
                            : "-";

                    /* -----------------------------
                       Table row weight reference
                       Open Cards mode has no month, so show
                       total progress since the client's first session.
                       Normal month mode keeps the original
                       previous-month-closing / current-month-closing logic.
                    ------------------------------*/
                    let referenceWeight;
                    let referenceSource;
                    let currentClosingWeight;
                    let monthDifference = 0;
                    let actualPreviousClosingWeight = 0;
                    let currentOpeningWeight = 0;

                    if (isCardView) {
                        referenceWeight = joinedWeight;
                        referenceSource = "Joined Weight";
                        currentClosingWeight = presentWeight;
                        monthDifference = totalChange;
                    } else {
                        actualPreviousClosingWeight = getLastAvailableWeight(previousSessions);
                        currentOpeningWeight = getFirstAvailableWeight(currentSessions);

                        referenceWeight = actualPreviousClosingWeight;
                        referenceSource = `${previousMonthLabel} Closing`;

                        if (!referenceWeight && currentOpeningWeight) {
                            referenceWeight = currentOpeningWeight;
                            referenceSource = `${selectedMonthLabel} Opening Used`;
                        }

                        currentClosingWeight = getLastAvailableWeight(currentSessions);

                        if (referenceWeight && currentClosingWeight) {
                            monthDifference = referenceWeight - currentClosingWeight;
                        }
                    }

                    const totalSessionsInPlan = toNumber(plan.total_sessions);
                    const completedThisMonth = currentSessions.filter(isSubmittedSession).length;

                    const rowKey = `${patientKey}__${selectedMonthKey}`;

                    const row = {
                        row_key: rowKey,
                        month_key: selectedMonthKey,
                        month_label: selectedMonthLabel,
                        previous_month_key: previousMonthKey,
                        previous_month_label: previousMonthLabel,
                        patient_key: patientKey,
                        patient: patientName,

                        mobile: patientMobileByName[patientKey] || "",
                        masked_mobile: maskMobileNumber(patientMobileByName[patientKey] || ""),

                        branch: plan.branch || "-",

                        previous_closing_weight: referenceWeight,
                        actual_previous_closing_weight: actualPreviousClosingWeight,
                        reference_source: referenceSource,
                        used_current_opening_as_reference: !actualPreviousClosingWeight && !!currentOpeningWeight,

                        current_closing_weight: currentClosingWeight,
                        month_difference: monthDifference,
                        completed_sessions: completedThisMonth,
                        total_sessions: totalSessionsInPlan,
                        first_session_date: firstSlimmingSessionDate || "-",
                        latest_session_date: latestSlimmingSessionDate || "-",
                        
                        is_open_card: isOpenCard,
                        is_closed_card: isClosedCard
                    };

                    rows.push(row);

                    rowDetailsMap[rowKey] = {
                        row: row,
                        plan: plan,
                        mobile: patientMobileByName[patientKey] || "",
                        maskedMobile: maskMobileNumber(patientMobileByName[patientKey] || ""),
                        currentSessions: currentSessions,
                        previousSessions: previousSessions,

                        lifetimeSessions: modalSessions,

                        joinedWeight: joinedWeight,
                        presentWeight: presentWeight,
                        totalChange: totalChange,

                        firstSessionDate: firstSlimmingSessionDate || "-"
                    };
                });

                rows.sort((a, b) => {
                    const branchCompare = String(a.branch || "").localeCompare(String(b.branch || ""));
                    if (branchCompare !== 0) return branchCompare;

                    return String(a.patient || "").localeCompare(String(b.patient || ""));
                });

                allTableRows = rows;

                void 0;

                applyFilters();

            } catch (err) {
                void 0;

                frappe.msgprint({
                    title: "Error",
                    message: "Failed to load report data. Please check browser console.",
                    indicator: "red"
                });
            }

            hideLoader();
        }

        function groupSessionsByPatient(sessions) {
            const grouped = {};

            (sessions || []).forEach(session => {
                const patientKey = getPatientDocKey(session.patient);
                if (!patientKey) return;

                if (!grouped[patientKey]) {
                    grouped[patientKey] = [];
                }

                grouped[patientKey].push(session);
            });

            return grouped;
        }

        /* =====================================================
           FILTERS
        ===================================================== */
        function applyFilters() {
            const branch = branchFilterEl?.value || "";
            const selectedClient = getPatientDocKey(selectedClientName);
            const weightLossFilter = weightLossFilterEl?.value || "";
            mainCurrentPage = 1;

            let filteredRows = [...allTableRows];

            if (branch) {
                filteredRows = filteredRows.filter(row => row.branch === branch);
            }
            
            if (weightLossFilter) {
    filteredRows = filteredRows.filter(row => {
        const diff = toNumber(row.month_difference);

        if (weightLossFilter === "one_and_above") {
            return diff > 1;
        }

        if (weightLossFilter === "two_and_above") {
            return diff > 2;
        }

        if (weightLossFilter === "three_and_above") {
            return diff > 3;
        }

        if (weightLossFilter === "gain") {
            return diff < 0;
        }

        if (weightLossFilter === "no_change") {
            return diff === 0;
        }

        return true;
    });
}

            if (selectedClient) {
                filteredRows = filteredRows.filter(row => {
                    return getPatientDocKey(row.patient) === selectedClient;
                });
            }

            renderTable(filteredRows);
            updateKpis(filteredRows);
        }


