                const results = Array.isArray(res.message) ? res.message : [];

                if (!results.length) {
                    clientListEl.innerHTML = `
                        <div class="wl-dropdown-item" style="color:#9ca3af; cursor:default;">
                            No clients found
                        </div>
                    `;
                    clientListEl.classList.remove("hidden");
                    return;
                }

                clientListEl.innerHTML = results.map(row => {
                    const value = row.value || "";
                    const description = row.description || value;

                    return `
                        <div 
                            class="wl-dropdown-item" 
                            data-value="${escapeHtml(value)}"
                            data-description="${escapeHtml(description)}"
                        >
                            <strong>${escapeHtml(value)}</strong><br>
                            <small>${escapeHtml(description)}</small>
