                if (mainPaginationEl) mainPaginationEl.innerHTML = "";
                return;
            }

            const totalPages = Math.ceil(currentTableRows.length / PAGE_LIMIT);

            if (mainCurrentPage > totalPages) {
                mainCurrentPage = 1;
            }

            const start = (mainCurrentPage - 1) * PAGE_LIMIT;
            const end = start + PAGE_LIMIT;
            const pageRows = currentTableRows.slice(start, end);

            weightTableBody.innerHTML = pageRows.map(row => {
                return `
                    <tr class="wl-clickable-row" data-row-key="${escapeHtml(row.row_key)}">
                        <td><b>${escapeHtml(row.month_label)}</b></td>
                        <td>${escapeHtml(row.patient)}</td>
                        <td>
                            ${displayKg(row.previous_closing_weight)}
                            <br>
                            <small class="${row.used_current_opening_as_reference ? "wl-reference-warning" : ""}">
                                ${escapeHtml(row.reference_source || `${row.previous_month_label} Closing`)}
                            </small>
                        </td>
                        <td>
                            ${displayKg(row.current_closing_weight)}
                            <br>
                            <small>${escapeHtml(row.month_label)} Closing</small>
                        </td>
                        <td class="${differenceClass(row.month_difference)}">
                            <b>${displayDifference(row.month_difference)}</b>
                        </td>
                        <td>
                            ${escapeHtml(row.completed_sessions)} / ${escapeHtml(row.total_sessions || "-")}
                        </td>
                        <td>${escapeHtml(row.branch)}</td>
                        
                    </tr>
                `;
            }).join("");

            

            weightTableBody.querySelectorAll(".wl-clickable-row").forEach(row => {
                row.onclick = function () {
                    const rowKey = this.getAttribute("data-row-key");
                    openDetailsModal(rowKey);
                };
            });

            renderPagination(
                mainPaginationEl,
                mainCurrentPage,
                totalPages,
                function (page) {
                    mainCurrentPage = page;
                    renderTable(currentTableRows);
                }
            );
        }

        /* =====================================================
           KPI
        ===================================================== */
        function updateKpis(rows) {
    rows = rows || [];

    const totalClients = rows.length;

    /*
     * Total loss is still calculated internally because
     * Average Weight Loss depends on it.
     */
    const totalLoss = rows.reduce((sum, row) => {
        const difference = toNumber(row.month_difference);

        return difference > 0
            ? sum + difference
            : sum;
    }, 0);

    const totalSessions = rows.reduce((sum, row) => {
        return sum + toNumber(row.completed_sessions);
    }, 0);

    const averageLoss =
        totalClients
            ? totalLoss / totalClients
            : 0;

    if (totalClientsEl) {
        totalClientsEl.innerText =
            totalClients.toLocaleString("en-IN");
    }

    /*
     * Total Open Cards is updated independently by
     * renderOpenCardsCount().
     */

    if (avgLossEl) {
        avgLossEl.innerText =
            averageLoss.toFixed(1) + " kg";
    }

    if (totalLossSummaryEl) {
        totalLossSummaryEl.innerText =
            totalLoss.toFixed(1) + " kg";
    }

    if (totalSessionsEl) {
        totalSessionsEl.innerText =
            totalSessions.toLocaleString("en-IN");
    }
}

        /* =====================================================
           MODAL
        ===================================================== */
        function openDetailsModal(rowKey) {
            const detail = rowDetailsMap[rowKey];

            if (!detail) return;

            const row = detail.row;

            if (modalClientName) {
                const maskedMobile = detail.maskedMobile || "";
            
                modalClientName.innerText = maskedMobile
                    ? `${row.patient || "Client Details"} — ${maskedMobile}`
                    : row.patient || "Client Details";
            }
            
            if (modalMonthInfo) {
                modalMonthInfo.innerText =
                    `${row.previous_month_label} vs ${row.month_label}`;
            }

            if (modalBranch) modalBranch.innerText = row.branch || "-";
            if (modalFirstSession) modalFirstSession.innerText = formatCustomDate(detail.firstSessionDate);
            if (modalJoinedWeight) modalJoinedWeight.innerText = displayKg(detail.joinedWeight);
            if (modalPresentWeight) modalPresentWeight.innerText = displayKg(detail.presentWeight);

            if (modalTotalLoss) {
                modalTotalLoss.innerText = displayDifference(detail.totalChange);
                modalTotalLoss.className = differenceClass(detail.totalChange);
            }

            if (modalTotalSessionSummary) {
                modalTotalSessionSummary.innerText =
                    `${detail.lifetimeSessions.length} / ${row.total_sessions || "-"}`;
            }

            if (modalPrevClosing) {
                modalPrevClosing.innerText = row.used_current_opening_as_reference
                    ? `${displayKg(row.previous_closing_weight)} (${row.reference_source})`
                    : displayKg(row.previous_closing_weight);
            }
            
            if (modalCurrentClosing) modalCurrentClosing.innerText = displayKg(row.current_closing_weight);

            if (modalMonthDifference) {
                modalMonthDifference.innerText = displayDifference(row.month_difference);
                modalMonthDifference.className = differenceClass(row.month_difference);
            }

            if (previousMonthTitle) {
                previousMonthTitle.innerText = `${row.previous_month_label} Sessions`;
            }

            if (currentMonthTitle) {
                currentMonthTitle.innerText = `${row.month_label} Sessions`;
            }

            renderSessionTable(previousMonthSessionsBody, detail.previousSessions);
            renderSessionTable(currentMonthSessionsBody, detail.currentSessions);

            if (modalOverlay) {
                modalOverlay.classList.remove("hidden");
            }
        }

        function closeModal() {
            if (modalOverlay) {
                modalOverlay.classList.add("hidden");
            }
        }

        function renderSessionTable(tbody, sessions) {
            if (!tbody) return;

            const sortedSessions = sortSessionsAsc(sessions || []);

            if (!sortedSessions.length) {
                tbody.innerHTML = `
                    <tr>
                        <td colspan="5" class="wl-empty-row">
                            No sessions found
                        </td>
                    </tr>
                `;
                return;
            }

            tbody.innerHTML = sortedSessions.map(session => {
                const diff = getSessionDifference(session);

                return `
                    <tr>
                        <td>${formatCustomDate(session.start_date)}</td>
                        <td>${escapeHtml(session.name || "-")}</td>
                        <td>${displayKg(session.before_weight)}</td>
                        <td>${displayKg(session.after_weight)}</td>
                        <td class="${differenceClass(diff)}">
                            ${displayDifference(diff)}
                        </td>
                    </tr>
                `;
            }).join("");
        }

        /* =====================================================
           PAGINATION
        ===================================================== */
        function renderPagination(container, currentPage, totalPages, onPageChange) {
            if (!container) return;

            if (totalPages <= 1) {
                container.innerHTML = "";
                return;
            }

            let buttons = "";

            buttons += `
                <button
                    class="wl-page-btn"
                    ${currentPage === 1 ? "disabled" : ""}
                    data-page="${currentPage - 1}">
                    Prev
                </button>
            `;

            const maxButtons = 7;
            let startPage = Math.max(1, currentPage - 3);
            let endPage = Math.min(totalPages, startPage + maxButtons - 1);

            if (endPage - startPage + 1 < maxButtons) {
                startPage = Math.max(1, endPage - maxButtons + 1);
            }

            for (let i = startPage; i <= endPage; i++) {
                buttons += `
                    <button
                        class="wl-page-btn ${i === currentPage ? "active" : ""}"
                        data-page="${i}">
                        ${i}
                    </button>
                `;
            }

            buttons += `
                <button
                    class="wl-page-btn"
                    ${currentPage === totalPages ? "disabled" : ""}
                    data-page="${currentPage + 1}">
                    Next
                </button>
            `;

            container.innerHTML = `
                <div class="wl-page-info">
                    Page ${currentPage} of ${totalPages}
                </div>
                <div class="wl-page-buttons">
                    ${buttons}
                </div>
            `;

            container.querySelectorAll(".wl-page-btn").forEach(btn => {
                btn.onclick = function () {
                    if (this.disabled) return;

                    const page = parseInt(this.getAttribute("data-page"), 10);

                    if (!page || page < 1 || page > totalPages) return;

                    onPageChange(page);
                };
            });
        }

        /* =====================================================
           RESET
        ===================================================== */
        function resetDashboard() {
    if (weightTableBody) {
        weightTableBody.innerHTML = "";
    }

    if (mainPaginationEl) {
        mainPaginationEl.innerHTML = "";
    }

    if (totalClientsEl) {
        totalClientsEl.innerText = "0";
    }

    /*
     * Do not reset Total Open Cards here because changing
     * the Month filter should not clear the all-time count.
     */

    if (avgLossEl) {
        avgLossEl.innerText = "0 kg";
    }

    if (totalLossSummaryEl) {
        totalLossSummaryEl.innerText = "0.0 kg";
    }

    if (totalSessionsEl) {
        totalSessionsEl.innerText = "0";
    }
}

    }, 500);
})();
